"""Offline, self-contained dynamic forecast backtest dashboard. No external JS/CDN."""
from pathlib import Path
import json
import pandas as pd
ROOT=Path(__file__).resolve().parents[1];R=ROOT/'results';DEST=ROOT/'report'
PACK={name:pd.read_csv(R/filename).to_dict('records') for name,filename in {
  'history':'forecast_weekly_history.csv','holdout':'forecast_holdout_weeks.csv',
  'evaluation':'forecast_evaluation.csv','selection':'forecast_model_selection.csv'}.items()}
PACK['summary']=json.loads((R/'forecast_summary.json').read_text())
data=json.dumps(PACK,ensure_ascii=False,separators=(',',':'))
html=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Retail Signals | Historical Demand Forecast Backtest</title>
<style>
:root{--bg:#0c1424;--panel:#18273d;--edge:#304761;--white:#f5f7fd;--muted:#aec0d1;--teal:#64decd;--peach:#ffb18e;--blue:#9fb2ff;--pink:#f18b9d}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 80% -25%,#24264d,transparent 50%),var(--bg);color:var(--white);font:15px 'Segoe UI',Arial,sans-serif}.wrap{max-width:1510px;margin:auto;padding:35px 38px 65px}.top{display:flex;align-items:center;justify-content:space-between;gap:20px;border-bottom:1px solid var(--edge);padding-bottom:20px}.brand{font-size:18px;font-weight:850;letter-spacing:.02em}.brand:before{content:'R';background:var(--teal);color:var(--bg);border-radius:8px;margin-right:11px;padding:6px 10px}.badge{border:1px solid #5b6b82;border-radius:25px;padding:7px 15px;color:var(--peach);font-size:12px;font-weight:750}.micro{color:var(--teal);font-weight:800;font-size:12px;letter-spacing:.12em}.eyebrow{margin:33px 0 12px}h1{font-size:clamp(28px,4vw,55px);margin:0 0 12px;letter-spacing:-.035em}h1 em{font-style:normal;color:var(--peach)}.deck{line-height:1.6;color:var(--muted);max-width:980px;margin:0 0 23px}.tabs{display:flex;gap:8px;margin:26px 0 19px;flex-wrap:wrap}.tab{display:inline-block;text-decoration:none;border:1px solid var(--edge);background:var(--panel);color:var(--muted);border-radius:10px;padding:12px 21px;font-weight:780}.tab.active{color:#091a27;background:var(--teal);border-color:var(--teal)}.tab:focus-visible,select:focus-visible{outline:3px solid var(--peach)}.control{background:var(--panel);border:1px solid var(--edge);padding:17px 22px;border-radius:13px;display:flex;gap:25px;align-items:center;flex-wrap:wrap;margin:18px 0}.control label{font-weight:750;color:var(--muted)}select{display:block;min-width:245px;max-width:100%;padding:11px 14px;margin-top:9px;border-radius:9px;color:var(--white);background:var(--bg);border:1px solid #4b617a;font-weight:650}.notice{color:var(--peach);font-size:12px;line-height:1.5;max-width:600px}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.card,.panel{border:1px solid var(--edge);border-radius:15px;background:var(--panel)}.card{min-height:126px;padding:19px 21px}.card .k{color:var(--muted);font-size:11px;letter-spacing:.04em;font-weight:780}.card .v{font-size:clamp(26px,2.6vw,42px);font-weight:850;margin:9px 0 3px;letter-spacing:-.04em}.card small{color:#90a5b8;font-size:11px}.cards .card:nth-child(2) .v{color:var(--teal)}.cards .card:nth-child(3) .v{color:var(--peach)}.cards .card:nth-child(4) .v{color:var(--blue)}.cols{display:grid;grid-template-columns:1.55fr 1fr;gap:15px;margin-top:16px}.panel{padding:25px 26px;min-width:0}h2{margin:0 0 7px;font-size:21px}.sub{font-size:13px;line-height:1.5;color:var(--muted);margin-bottom:22px}svg{display:block;max-width:100%;height:auto}.legend{display:flex;gap:18px;flex-wrap:wrap;color:var(--muted);font-size:12px;margin:16px 0}.dot{width:10px;height:10px;display:inline-block;margin-right:5px;border-radius:3px}.row{display:grid;grid-template-columns:68px 1fr 1fr;gap:11px;align-items:center;padding:14px 0;border-bottom:1px solid #30445c;color:var(--muted);font-size:14px}.row strong{color:var(--white);text-align:right}.note{background:#28293b;border:1px solid #5c4b66;padding:21px 23px;border-radius:13px;margin:17px 0;line-height:1.6}.note strong{color:var(--peach)}footer{margin-top:29px;border-top:1px solid var(--edge);color:var(--muted);font-size:12px;padding-top:20px;line-height:1.65}@media(max-width:920px){.wrap{padding:15px}.cards{grid-template-columns:repeat(2,1fr)}.cols{grid-template-columns:1fr}}@media(max-width:530px){.cards{grid-template-columns:1fr}.top{align-items:flex-start;flex-direction:column}}
</style></head><body><main class="wrap"><header class="top"><div class="brand">RETAIL / INTELLIGENCE</div><div class="badge">HISTORICAL MODEL EXPERIMENT · NOT LIVE FORECAST</div></header><div class="eyebrow micro">FORECASTING / 03</div><h1>Could I have <em>seen the surge coming?</em></h1><p class="deck">The sales analysis showed that orders were rising. The next question was whether a simple forecasting method could anticipate actual weekly units sold — without accidentally learning from the weeks it was supposed to predict.</p>
<nav class="tabs"><a class="tab" href="interactive_dashboard.html">01 / Sales & markets</a><a class="tab" href="interactive_dashboard.html#pgCustomer">02 / Customers & cohorts</a><a class="tab active" href="forecast_experiment.html" aria-current="page">03 / Forecasting</a></nav>
<div class="control"><label>Forecast series<select id="series"></select></label><div class="notice">Pick an individual product or all products. Models were selected only using earlier expanding-window validation periods. The November test period was held out until the final evaluation.</div></div>
<div class="cards"><div class="card"><div class="k">OBSERVED UNITS · FINAL 4 WEEKS</div><div id="observed" class="v">—</div><small>7 Nov through 4 Dec 2011</small></div><div class="card"><div class="k">SELECTED MODEL FORECAST</div><div id="estimated" class="v">—</div><small id="method">Model chosen in earlier folds</small></div><div class="card"><div class="k">FINAL TEST ERROR</div><div id="error" class="v">—</div><small>Four-week WAPE · lower is better</small></div><div class="card"><div class="k">SIMPLE MODEL ERROR</div><div id="baseline" class="v">—</div><small>Trailing four-week mean forecast</small></div></div>
<div class="cols"><article class="panel"><h2>What the model knew — and predicted</h2><div class="sub">The historical line ends at the final observed week. The highlighted area was forecast using only pre-holdout weeks.</div><div id="plot" role="img" aria-label="Weekly units sales and forecast chart"></div><div class="legend"><span><i class="dot" style="background:var(--white)"></i>Observed weekly units</span><span><i class="dot" style="background:var(--teal)"></i>Selected forecast</span><span><i class="dot" style="background:var(--blue)"></i>Simple baseline</span></div></article><article class="panel"><h2>Inside the held-out four weeks</h2><div class="sub">Observed and predicted units by week. Both forecasts were frozen before the holdout started.</div><div class="row"><b>WEEK OF</b><b style="text-align:right">OBSERVED</b><b style="text-align:right">PREDICTED</b></div><div id="weeklyRows"></div><div class="note"><strong>What the errors mean</strong><br>WAPE adds up absolute weekly forecast errors and divides by actual units sold during the test. It is not an accuracy percentage, and it does not account for future promotions or inventory restrictions.</div></article></div>
<div class="note"><strong>The limitation I couldn't model away:</strong> this dataset covers about one year of filtered positive sales. It contains no stock availability, unfilled orders, advertising, promotion calendar or reliable multi-year holiday pattern. The quantity sold is a useful signal, but it is not unconstrained customer demand. The 2010 holiday week without transactions is kept as zero observed sales — this does not prove customers wanted nothing.</div>
<footer>Reproducibility: scripts/demand_forecast.py generates five non-overlapping, out-of-time four-week validation folds, chooses from three transparent forecasting methods per series, and evaluates one final untouched November–December 2011 four-week period. No data from the final holdout influenced method selection. All displayed numbers are calculated from the aggregated results in this repository.</footer>
</main><script>const DATA=__EMBED__;const $=id=>document.getElementById(id);const fmt=v=>Math.round(v).toLocaleString('en-GB');
for(const row of DATA.evaluation){const o=document.createElement('option');o.value=row.Series;o.textContent=row.Series==='All products'?'ALL PRODUCTS':`${row.Series} / ${row.Product}`;$('series').appendChild(o)}
function paint(){const k=$('series').value,z=DATA.evaluation.find(x=>x.Series===k),m=DATA.selection.find(x=>x.Series===k),rows=DATA.holdout.filter(x=>x.Series===k),h=DATA.history.slice(-19);$('observed').textContent=fmt(z.ActualTotal);$('estimated').textContent=fmt(z.ForecastTotal);$('error').textContent=z.HoldoutWAPE.toFixed(1)+'%';$('baseline').textContent=z.BaselineHoldoutWAPE.toFixed(1)+'%';$('method').textContent=m.Method.replaceAll('_',' ')+' / selected pre-holdout';$('weeklyRows').innerHTML=rows.map(r=>`<div class="row"><span>${r.WeekStart.slice(5)}</span><strong>${fmt(r.ActualUnits)}</strong><strong style="color:var(--teal)">${fmt(r.ForecastUnits)}</strong></div>`).join('');
const W=850,H=365,l=63,r=12,t=20,b=57,x=i=>l+i*(W-l-r)/(h.length-1),weeks=h.map(w=>w.WeekStart),v=h.map(w=>w[k]),max=Math.max(...v,...rows.map(r=>r.ForecastUnits)) *1.13,y=n=>H-b-n/max*(H-t-b);let s=`<svg viewBox="0 0 ${W} ${H}" aria-label="Nineteen-week series with final four weeks marked as holdout">`;for(let n=0;n<5;n++){let yy=t+(H-b-t)*n/4;s+=`<line x1="${l}" y1="${yy}" x2="${W-r}" y2="${yy}" stroke="#354b62"/><text x="${l-8}" y="${yy+4}" text-anchor="end" fill="#aec0d1" font-size="11">${fmt(max*(4-n)/4)}</text>`}const boundary=weeks.indexOf(rows[0].WeekStart);if(boundary>0){const left=(x(boundary-1)+x(boundary))/2;s+=`<rect x="${left}" y="${t}" width="${W-r-left}" height="${H-b-t}" fill="#304761" opacity=".34"/>`}s+=`<polyline points="${v.map((w,i)=>`${x(i)},${y(w)}`).join(' ')}" fill="none" stroke="#f5f7fd" stroke-width="2.4" stroke-linejoin="round"/>`;for(let i=0;i<h.length;i++){if(i===0||i%3===0||i===h.length-1){s+=`<text x="${x(i)}" y="${H-26}" text-anchor="middle" fill="#aec0d1" font-size="11">${weeks[i].slice(5)}</text>`}}const pts=rows.map(row=>[weeks.indexOf(row.WeekStart),row]);s+=`<polyline points="${pts.map(([i,w])=>`${x(i)},${y(w.ForecastUnits)}`).join(' ')}" fill="none" stroke="#64decd" stroke-width="3.8" stroke-dasharray="8 4"/><polyline points="${pts.map(([i,w])=>`${x(i)},${y(w.BaselineUnits)}`).join(' ')}" fill="none" stroke="#9fb2ff" stroke-width="2.7" stroke-dasharray="3 5"/>`;for(const [i,row] of pts){s+=`<circle cx="${x(i)}" cy="${y(row.ForecastUnits)}" r="4.5" fill="#64decd"><title>${row.WeekStart}: ${fmt(row.ForecastUnits)} forecast units</title></circle>`}s+='</svg>';$('plot').innerHTML=s}
$('series').addEventListener('change',paint);paint();</script></body></html>'''
html=html.replace('__EMBED__',data)
(DEST/'forecast_experiment.html').write_text(html,encoding='utf8')
print('Saved offline forecast dashboard',len(html.encode()))
